import unittest

from solution import expand_ranges


class ExpandRangesTests(unittest.TestCase):
    def test_normal_expansion_is_inclusive_and_ordered(self):
        self.assertEqual(expand_ranges("2,5-7,3"), [2, 5, 6, 7, 3])

    def test_singleton_range_and_duplicates(self):
        self.assertEqual(expand_ranges("4-4,4,2-3,2"), [4, 4, 2, 3, 2])

    def test_whitespace_and_leading_zeroes(self):
        self.assertEqual(expand_ranges(" 001 , 3 - 5 , 0 "), [1, 3, 4, 5, 0])

    def test_empty_input(self):
        self.assertEqual(expand_ranges(""), [])
        self.assertEqual(expand_ranges(" \t\n "), [])

    def test_invalid_specifications(self):
        invalid = [
            ",", "1,", ",1", "1,,2", "-1", "1,-2", "1-", "-1-2",
            "3-2", "1-2-3", "a", "1-b", "1.0", "+1", "1 2",
        ]
        for spec in invalid:
            with self.subTest(spec=spec):
                with self.assertRaises(ValueError):
                    expand_ranges(spec)

    def test_non_string_input(self):
        for value in [None, 12, ["1-2"], b"1-2"]:
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    expand_ranges(value)


if __name__ == "__main__":
    unittest.main()

